// Filtrar solo filas con estado PENDIENTE o SIN_USAR
const rows = $input.all();
const pendingRow = rows.find(row => 
  row.json.ESTADO === 'PENDIENTE' || 
  row.json.ESTADO === 'SIN_USAR' ||
  row.json.ESTADO === 'PTE'
);

if (!pendingRow) {
  throw new Error('No hay temas pendientes en esta hoja');
}

return [pendingRow];

// Manejo de errores: si algo falla, marcar como ERROR en la hoja
try {
  return $input.all();
} catch (error) {
  // Aquí iría lógica para actualizar estado a ERROR
  throw error;
}
